// ─── Master Openings Book Database (Deep 10-16 Plies Multi-Move Tree) ─────────
// High-grade ECO database covering all major opening families with deep 10-16 plies
// continuation paths, candidate moves, win/draw/loss statistics, and evaluation scores.

export interface OpeningMoveStats {
  san: string;
  uci: string;
  games: number;
  white: number; // White win %
  draw: number;  // Draw %
  black: number; // Black win %
  eval?: number; // Approximate computer evaluation
  name?: string; // Variation name
}

export interface TopMasterGame {
  white: string;
  black: string;
  res: string;
  year: number;
  event: string;
}

export interface OpeningBookNode {
  name: string;
  eco: string;
  category: string;
  description: string;
  moves: OpeningMoveStats[];
  topGames?: TopMasterGame[];
}

export interface OpeningVariationLine {
  eco: string;
  name: string;
  category: string;
  moves: string[];
  description: string;
}

